\begin{corollary}[Retained-port girth and circuit heads]\label{thm:retained}
For early reports and retained ports, if $g<\infty$, then under the native rational resource certificate in
Section~\ref{subsec:price-native},
\begin{equation}
 V_{R,\mathrm{early}}(\delta)
 =\left(\sum_{i\in\mathcal H_g}A_i\right)
   \ell_g(1/\delta)(1+o(1)).
 \label{eq:price-retained}
\end{equation}
If $g=\infty$, zero observations suffice, with all actual correction and
normal charges retained. The lower-bound direction does not require the
sufficient quota test. This statement concerns statistical value;
it does not posit a polynomial girth oracle for a general input graph.
\end{corollary}

\begin{lemma}[Extension by one compatible tool]
\label{lem:laminar-extension}
Let $c$ be normalized, let $D\in\mathcal I(c)$, and let
$\varnothing\ne S\in\mathcal L$.  There exists
$r\in S\setminus D$ such that $D\cup\{r\}\in\mathcal I(c)$ if and
only if
\begin{equation}
 |D\cap T|<c_T\qquad\text{for every }T\in\mathcal A(S).
 \label{eq:laminar-strict-path}
\end{equation}
When it exists, such a tool can be found by a descent in the tree.
\end{lemma}

\begin{lemma}[Rank and leading penalty coefficient]\label{lem:price-penalty-asymptotic}
At a fixed healthy state, $\rho=\infty$ implies $G=0$.  If
$\rho(i,R)=d<\infty$, then
\begin{equation}
 G_{i,R}(\lambda)=C(i,R)\ell_d(\lambda)(1+o(1)),\qquad C(i,R)>0.
 \label{eq:price-penalty-asymptotic}
\end{equation}
\end{lemma}

\begin{theorem}[Separation of correction prices]
\label{thm:paid:separation}
Under \eqref{eq:paid:cap-certificate}, set
$A=V_0^{\rm nat}(\delta)$ with the \emph{same} $I_{\rm pay}$ contract,
original quotas, call cap and target risk.  Put
\begin{equation}
 D_f=aN\log(1+f/a),\qquad
 S_\delta=aN\log(1+N/\delta),\qquad
 T=\min\{A+D_f,S_\delta\}.
 \label{eq:paid:three-scales}
\end{equation}
Then
\begin{equation}
 T/129\le V_f^{\rm nat}(\delta)\le72T.
 \label{eq:paid:main-separation}
\end{equation}
The constants are independent of all parameters and original resources.
An explicit rational algorithm, receiving neither $A$ nor an optimal
free policy, produces a native $\delta$-safe policy satisfying
\begin{equation}
 V_f^\infty(\delta)\le V_f^{\rm nat}(\delta)
 \le\E C_{\rm alg}\le8V_f^\infty(\delta).
 \label{eq:paid:algorithm-sandwich}
\end{equation}
Its computation and bit complexity are given in
Appendix~\ref{sec:paid:implementation}; polynomial dependence on
$\log(1/\gamma)$ is not asserted.
\end{theorem}

\begin{lemma}[Stopped information]
\label{lem:paid:information}
For every experiment with finite expected review count,
\begin{equation}
 c\E T=a\E\phi(P).
 \label{eq:paid:information}
\end{equation}
The identity also holds after restriction to an event determined before
the current fresh fact is born.  A fact filled blindly for analysis has
$T=0$ and $P=1/2$.
\end{lemma}

\begin{lemma}[Actual-usage bound for current payment]
\label{lem:paid:usage}
For every native $\delta$-safe policy, if $r=\E R_{\rm act}$ and
$m=N(1-\delta)$, then
\begin{equation}
 \E C\ge a\mathcal H(m,r+\delta)+fr.
 \label{eq:paid:usage}
\end{equation}
The same inequality holds for finite-cost cap-relaxed policies.
\end{lemma}

\begin{lemma}[Uniform fee scale]
\label{lem:paid:fee-scale}
Every $\delta$-safe current-payment policy satisfies
\begin{equation}
 \E C\ge\frac{aN}{128}
       \log\left(1+\min\{f/a,N/\delta\}\right).
 \label{eq:paid:fee-scale}
\end{equation}
\end{lemma}

\begin{theorem}[Paid overlay]
\label{thm:paid:overlay}
For every finite-cost free-correction policy $\pi_0$, there is a
current-payment policy $\pi_f$ with no larger failure probability and
\begin{equation}
 \E C(\pi_f)\le\E C_{\rm obs}(\pi_0)
       +\tfrac{17}{2}Na\log(1+f/a).
 \label{eq:paid:overlay-policy}
\end{equation}
In particular
\begin{equation}
 V_f^\infty(\delta)\le V_0^\infty(\delta)+9D_f.
 \label{eq:paid:overlay-value}
\end{equation}
\end{theorem}

\begin{lemma}[No-correction comparison]
\label{lem:paid:no-correction}
In the cap-relaxed model,
$V_f^\infty(\delta)\le7S_\delta$ for every $f\ge0$.
\end{lemma}

