\subsection{Main results and their different quantifiers}
\paragraph{Compact causal safety is the structural result.}
The game rank $\rho$ is the minimum adaptive error budget forcing an
unrepairable output against an optimal causal allocator. For arbitrary
known order and laminar stage eligibility, Theorem~\ref{thm:laminar}
represents every suffix and error-budget safety family by capacities on
the same tree. It preprocesses in $O((N+1)(q+1)t)$ operations and answers
rank and maximizing-tool queries in $O((q+1)t)$, where $t\le N+q+1$.
The number of tools and stages may vary. No exponential subset table or
precomputed strategy is an input.

Let $\rho(i,R)$ denote the adaptive current-window game value, with
$\rho(N+1,R)=\infty$.  At a healthy state define
\begin{align}
 d_g&=\rho(i+1,R),\nonumber\\
 d_b&=\begin{cases}
 0,&S_i\cap R=\varnothing,\\
 \displaystyle\max_{r\in S_i\cap R}\rho(i+1,R\setminus\{r\}),&\text{otherwise},
 \end{cases}
 \qquad \rho(i,R)=\min\{d_g,1+d_b\}.
 \label{eq:price-rank}
\end{align}
More remaining tools can only help, so $d_g\ge d_b$.
Set $C(i,R)=0$ at infinite-rank states.  At a finite-rank state
$d=\rho(i,R)$ set
\begin{equation}
 C(i,R)=\ind\{d_g=d\}C(i+1,R)
       +\ind\{d_b+1=d\}A_i.
 \label{eq:price-coefficient}
\end{equation}

\section{Proof of the compact safety representation}
\label{app:laminar}
We prove Theorem~\ref{thm:laminar} by representing sets of \emph{used} tools, rather
than enumerating sets of remaining tools.

\subsection{Capacity families and normalization}

For an integer vector $c=(c_T:T\in\mathcal L)$, define
\begin{equation}
 \mathcal I(c)
 =\bigl\{D\subseteq U:
          |D\cap T|\le c_T\text{ for every }T\in\mathcal L\bigr\}.
 \label{eq:laminar-capacity-family}
\end{equation}
Here $D$ will be the used-tool set, so the available tools are $U\setminus D$.
We also use the separate symbol $\mathsf{VOID}$ for the empty family.
It cannot be identified with the vector of all zero capacities: that
vector represents the nonempty family $\{\varnothing\}$.

For any family $\mathcal I$ and any stage set $S$, define its
one-tool extension family by
\begin{equation}
 \mathcal E_S(\mathcal I)
 =\{D\subseteq U:\exists r\in S\setminus D,
                         \ D\cup\{r\}\in\mathcal I\}.
 \label{eq:laminar-extension-family}
\end{equation}

\subsection{The exact error-budget recurrence}

For $k\ge0$, let
\begin{equation}
 \mathcal I_{i,k}
 =\bigl\{D\subseteq U:
    \text{the allocator can handle every adaptive pattern of at most
    $k$ errors from $(i,U\setminus D)$}\bigr\}.
 \label{eq:laminar-safe-family}
\end{equation}
Handling a pattern means legally allocating every erroneous stage;
correct stages use no tool.  In particular,
\begin{equation}
 \mathcal I_{i,0}=2^U,
 \qquad
 \mathcal I_{N+1,k}=2^U.
 \label{eq:laminar-boundary}
\end{equation}
The free family $2^U$ is represented by $c_T=|T|$.

For every $k>0$, the game quantifiers give
\begin{equation}
 \boxed{\displaystyle
 \mathcal I_{i,k}
 =\mathcal I_{i+1,k}
    \cap\mathcal E_{S_i}(\mathcal I_{i+1,k-1}).}
 \label{eq:laminar-budget-dp}
\end{equation}
Indeed the adversary may declare stage $i$ correct and retain its entire
budget, which requires membership in the first family.  Alternatively
it may spend one error, after which the allocator must choose an unused
compatible tool and retain a strategy against at most $k-1$ further
errors.  The subsequent strategy may depend on the selected tool, and
the adversary may observe that tool before continuing.  These are
precisely the extension-family quantifiers in the second term.  Thus
\eqref{eq:laminar-budget-dp} does not replace an adaptive adversary by
a fixed error subsequence.

Membership in these families recovers the game rank:
\begin{equation}
 D\in\mathcal I_{i,k}
 \quad\Longleftrightarrow\quad
 \rho(i,U\setminus D)>k,
 \label{eq:laminar-rank-membership}
\end{equation}
where $\infty>k$.  Only $k=0,\ldots,q+1$ are needed.  To see the
bound, a successful error consumes one previously unused tool.  On any
path, the first unrepairable error, if it occurs, is therefore among
the first $|R|+1$ errors.  Hence a finite value of $\rho(i,R)$ is at
most $|R|+1\le q+1$.  It follows that
\begin{equation}
 \rho(i,R)
 =\min\{k\in\{1,\ldots,q+1\}:
                   U\setminus R\notin\mathcal I_{i,k}\},
 \label{eq:laminar-rank-extraction}
\end{equation}
with the empty minimum interpreted as $\infty$.
Budgets exceeding the number of remaining stages require no additional
convention: the recurrence already accounts for the absence of further
error opportunities.  The terminal rank is consequently $\infty$ even
when no tool remains.

\subsection{Extracting a maximizing causal allocation}

The table also avoids enumerating tool choices when extracting the
maximal erroneous-successor rank.  At a current state $(i,R)$ with
$i\le N$, put $D=U\setminus R$ and compute
$d_T=|D\cap T|$ for all tree nodes.  For each $k=0,\ldots,q+1$, define
$e_k$ to be true if and only if all of the following hold:
\begin{enumerate}[label=(\roman*)]
\item $S_i\ne\varnothing$ and $\mathcal I_{i+1,k}$ is not
$\mathsf{VOID}$;
\item $D$ satisfies its capacity vector $c^{i+1,k}$;
\item $d_T<c^{i+1,k}_T$ for every $T\in\mathcal A(S_i)$.
\end{enumerate}
Lemma~\ref{lem:laminar-extension} and
\eqref{eq:laminar-rank-membership} give the exact equivalence
\begin{equation}
 e_k
 \quad\Longleftrightarrow\quad
 \exists r\in S_i\cap R:
                 \rho(i+1,R\setminus\{r\})>k.
 \label{eq:laminar-bad-existence}
\end{equation}
These predicates are nonincreasing in $k$.

\section{Proof of the fixed-structure statistical laws}
\label{app:prices}
\subsection{A local sequential experiment}

For a fresh stage-$i$ fact define the unconstrained local penalty value
\[
 J_i(t)=\inf_{T,\widehat X}
 \E\bigl[c_iT+t\ind\{\widehat X\ne X_i\}\bigr],\qquad t\ge0.
\]
This infimum allows randomized sequential tests and non-MAP decisions.
Dropping a native observation cap here only strengthens a lower-bound
comparator; it does not give extra calls to an implemented policy.

\begin{lemma}[Local logarithmic price]\label{lem:price-local}
For the fixed stage-$i$ experiment,
\[
 J_i(t)=A_i\log t\,(1+o(1))\quad(t\to\infty),\qquad
 0\le J_i(t)\le t.
\]
Moreover $J_i(t)=O_i(\log(1+t))$ for all $t\ge0$.
\end{lemma}

\subsection{One task-failure penalty and the full-history bridge}

In a relaxed problem drop nonnegative correction charges and all resource
caps, and charge a single penalty $\lambda>0$ for task failure.  Let its
value at a healthy state be $G_{i,R}(\lambda)$.  Put $G_{N+1,R}=0$ and set
\begin{align}
 G_g&=G_{i+1,R},\nonumber\\
 G_b&=\begin{cases}
 \lambda,&S_i\cap R=\varnothing,\\
 \displaystyle\min_{r\in S_i\cap R}G_{i+1,R\setminus\{r\}},&\text{otherwise}.
 \end{cases}
 \label{eq:price-successors}
\end{align}
Resource monotonicity gives $0\le G_g\le G_b\le\lambda$.  The exact relaxed
recursion is
\begin{equation}
 G_{i,R}=\min\{\lambda,\ G_g+J_i(G_b-G_g)\}.
 \label{eq:price-penalty}
\end{equation}

The actual certificate need not compute KL or real logarithms.  For rational
input set
\begin{align}
 E_\delta&=\min\{e\in\mathbb Z_{\ge1}:2^e\ge2NC_N/\delta\},\nonumber\\
 \underline d_i&=2\operatorname{TV}(P_i^0,P_i^1)^2>0,\nonumber\\
 \widehat Q_i&=\left\lceil\max\left\{
 \frac{2(E_\delta+\overline L_i)}{\underline d_i},\quad
 \frac{8\overline M_i^2E_\delta}{\underline d_i^2}
 \right\}\right\rceil.
 \label{eq:price-rational-quota}
\end{align}
Here integers $\overline M_i\ge M_i$ and $\overline L_i\ge L_i$ are
obtained by comparing the relevant rational ratios and their reciprocals
with integer powers of two.  Pinsker's inequality gives
$\underline d_i\le d_i$, and $E_\delta$ bounds both logarithms in
\eqref{eq:price-analytic-quota}, so $\widehat Q_i\ge Q_i$.

\begin{theorem}[Separation of correction prices]
\label{thm:paid:separation}
Under \eqref{eq:paid:cap-certificate}, set
$A=V_0^{\rm nat}(\delta)$ with the \emph{same} $I_{\rm pay}$ contract,
original quotas, call cap and target risk.  Put
\begin{equation}
 D_f=aN\log(1+f/a),\qquad
 S_\delta=aN\log(1+N/\delta),\qquad
 T=\min\{A+D_f,S_\delta\}.
 \label{eq:paid:three-scales}
\end{equation}
Then
\begin{equation}
 T/129\le V_f^{\rm nat}(\delta)\le72T.
 \label{eq:paid:main-separation}
\end{equation}
The constants are independent of all parameters and original resources.
An explicit rational algorithm, receiving neither $A$ nor an optimal
free policy, produces a native $\delta$-safe policy satisfying
\begin{equation}
 V_f^\infty(\delta)\le V_f^{\rm nat}(\delta)
 \le\E C_{\rm alg}\le8V_f^\infty(\delta).
 \label{eq:paid:algorithm-sandwich}
